import{_ as i,o as a,c as s,a5 as t}from"./chunks/framework.DrDMl0tG.js";const n="/assets/rayrai_runtime_scene_editing.F-_U27Oc.png",g=JSON.parse('{"title":"Rayrai Example: Runtime Scene Editing","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_runtime_scene_editing.md","filePath":"sections/examples/rayrai/rayrai_runtime_scene_editing.md"}'),r={name:"sections/examples/rayrai/rayrai_runtime_scene_editing.md"};function l(o,e,h,d,p,c){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="rayrai-example-runtime-scene-editing" tabindex="-1">Rayrai Example: Runtime Scene Editing <a class="header-anchor" href="#rayrai-example-runtime-scene-editing" aria-label="Permalink to &quot;Rayrai Example: Runtime Scene Editing&quot;">​</a></h1><p><img src="'+n+`" alt="rayrai_runtime_scene_editing example"></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Visualizes runtime scene editing operations that are useful for reset-heavy workloads: stable object id lookup, single-body snapshots, collision filter changes, cloning, and object removal.</p><p>Use this example when building reset, randomization, replay, or scripted scene editing workflows. It shows how to mutate a running world between simulation steps without reconstructing the whole world.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>rayrai_runtime_scene_editing</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Run the build-tree executable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_runtime_scene_editing</span></span></code></pre></div><p>On Windows, run <code>rayrai_runtime_scene_editing.exe</code> instead. This example renders in process with rayrai and does not need <code>rayrai_tcp_viewer</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Captures and restores a <code>World::SingleBodySnapshot</code>.</li><li>Clones a primitive single-body object with <code>cloneSingleBodyObject</code>.</li><li>Looks up a body by its stable object id with <code>World::getObjectById</code>.</li><li>Toggles the sphere collision mask with <code>World::setObjectCollisionFilter</code> during the simulation.</li><li>Removes and recreates a cloned body while the world is running.</li></ul><h2 id="what-to-look-for" tabindex="-1">What to look for <a class="header-anchor" href="#what-to-look-for" aria-label="Permalink to &quot;What to look for&quot;">​</a></h2><p>The scene contains a source box, a cloned box, and a sphere. During the loop:</p><ul><li>The source box is restored from a snapshot and relaunched.</li><li>The cloned box is periodically removed and recreated.</li><li>Every 240 steps, the sphere switches between colliding with everything and a zero collision mask. With the zero mask it passes through the ground and is drawn gray and translucent.</li></ul><p>These operations are intentionally visible so users can verify that the object state changes are reflected by rayrai immediately.</p><h2 id="api-pattern" tabindex="-1">API pattern <a class="header-anchor" href="#api-pattern" aria-label="Permalink to &quot;API pattern&quot;">​</a></h2><p>The important pattern is:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">raisim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">World</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::SingleBodySnapshot snapshot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">world-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">captureSingleBodySnapshot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(body, snapshot);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">world-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">restoreSingleBodySnapshot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(body, snapshot);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> clone </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> world-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cloneSingleBodyObject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(body, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;clone&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">world-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setObjectCollisionFilter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(clone, group, mask);</span></span></code></pre></div><p>Call these APIs between simulation steps. The example keeps the world single-threaded and performs all edits from the same loop that calls <code>world-&gt;integrate()</code>.</p>`,21)])])}const u=i(r,[["render",l]]);export{g as __pageData,u as default};
